use serde::{Deserialize, Serialize, Serializer};

use crate::{Diagnostic, DiagnosticCode, DiagnosticSeverity, PackageId, Version, VersionGrammar, VersionParseError};

/// A validated tag template containing prefix, suffix, and exact `{version}` placement.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Deserialize)]
#[serde(try_from = "String")]
pub struct TagTemplate {
    prefix: String,
    suffix: String,
}

impl TagTemplate {
    pub fn parse(raw: &str) -> Result<Self, TagTemplateError> {
        let version_marker = "{version}";
        let count = raw.matches(version_marker).count();
        if count == 0 {
            if let Some(start) = raw.find('{') {
                if let Some(end) = raw[start..].find('}') {
                    let placeholder = &raw[start + 1..start + end];
                    return Err(TagTemplateError::UnknownPlaceholder {
                        template: raw.to_string(),
                        placeholder: placeholder.to_string(),
                    });
                }
            }
            return Err(TagTemplateError::MissingVersionPlaceholder {
                template: raw.to_string(),
            });
        }
        if count > 1 {
            return Err(TagTemplateError::MultipleVersionPlaceholders {
                template: raw.to_string(),
                count,
            });
        }

        let (prefix, suffix) = raw.split_once(version_marker).unwrap();

        if prefix.is_empty() && suffix.is_empty() {
            return Err(TagTemplateError::NoLiteralAnchor {
                template: raw.to_string(),
            });
        }

        for (part, _name) in [(prefix, "prefix"), (suffix, "suffix")] {
            for ch in part.chars() {
                if matches!(ch, '*' | '?' | '[' | ']') {
                    return Err(TagTemplateError::GlobMetacharacterInLiteral {
                        template: raw.to_string(),
                        ch,
                    });
                }
            }
        }

        let test_render = format!("{prefix}1.0.0{suffix}");
        if !is_valid_git_ref_name(&test_render) {
            return Err(TagTemplateError::InvalidGitRefName {
                template: raw.to_string(),
                rendered: test_render,
            });
        }

        Ok(TagTemplate {
            prefix: prefix.to_string(),
            suffix: suffix.to_string(),
        })
    }

    /// `{name}@{version}` from the package's native name, so promotion to `eco/name` never changes its tags.
    pub fn default_for(id: &PackageId) -> Self {
        TagTemplate {
            prefix: format!("{}@", id.display_name()),
            suffix: String::new(),
        }
    }

    pub fn render(&self, version: &Version) -> TagName {
        // Unchecked: `prefix`/`suffix` already passed `is_valid_git_ref_name`
        // against a `1.0.0` stand-in at `TagTemplate::parse` time (rejecting
        // a leading `-`, control characters, `..`, `@{`, and per-component
        // `.lock` suffixes on that literal). `version.render()` is
        // Callisto's own trusted SemVer/PEP 440 rendering, never
        // attacker-controlled text, and its first character is always a
        // digit -- never `-` or a control character. That probe cannot rule
        // out every conceivable rendered version (for example, build
        // metadata literally ending in `.lock`), but it does rule out the
        // flag-injection-relevant leading-`-` and control-character cases
        // `TagName::parse` exists to catch.
        TagName::new_unchecked(format!("{}{}{}", self.prefix, version.render(), self.suffix))
    }

    pub fn render_floating_major(&self, version: &Version) -> Option<TagName> {
        let major = version.major()?;
        let rendered = format!("{}{}{}", self.prefix, major, self.suffix);
        TagName::parse(&rendered).ok()
    }

    pub fn glob(&self) -> String {
        format!("{}*{}", self.prefix, self.suffix)
    }

    pub fn extract_version_str<'a>(&self, tag: &'a str) -> Option<&'a str> {
        if !tag.starts_with(&self.prefix) || !tag.ends_with(&self.suffix) {
            return None;
        }
        let end_idx = tag.len() - self.suffix.len();
        if end_idx < self.prefix.len() {
            return None;
        }
        Some(&tag[self.prefix.len()..end_idx])
    }

    pub fn as_str(&self) -> String {
        format!("{}{{version}}{}", self.prefix, self.suffix)
    }
}

impl Serialize for TagTemplate {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&self.as_str())
    }
}

impl TryFrom<String> for TagTemplate {
    type Error = TagTemplateError;

    fn try_from(raw: String) -> Result<Self, Self::Error> {
        Self::parse(&raw)
    }
}

fn is_valid_git_ref_name(s: &str) -> bool {
    if s.is_empty() || s.starts_with('/') || s.ends_with('/') || s.contains("//") || s == "@" {
        return false;
    }
    // Git ref names may legally start with `-`, but every caller in this
    // codebase passes the rendered name as a bare positional to `git tag`
    // (or an equivalent CLI), whose argument parser treats a leading `-`
    // as an option rather than a ref name -- reject it here so a malicious
    // or accidental `tag-template` can never produce one.
    if s.starts_with('-') {
        return false;
    }
    if s.contains("..") || s.contains("@{") {
        return false;
    }
    for component in s.split('/') {
        if component.starts_with('.') || component.ends_with(".lock") {
            return false;
        }
    }
    for ch in s.chars() {
        if ch.is_ascii_control() || ch == ' ' || matches!(ch, '~' | '^' | ':' | '?' | '*' | '[' | '\\') {
            return false;
        }
    }
    true
}

use schemars::JsonSchema;

/// Rendered Git tag name.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, JsonSchema, Deserialize)]
#[schemars(with = "String")]
#[serde(try_from = "String")]
pub struct TagName(String);

impl TagName {
    /// Parses a Git tag name, rejecting anything `git check-ref-format`
    /// would reject (control characters, `..`, `@{`, a `.lock`-suffixed or
    /// leading-`.` component, reserved characters, and the rest of
    /// the remaining Git ref-name rules) plus a leading `-`, which is a legal Git
    /// ref character but would be read as a flag by any CLI argument
    /// parser (`git`, `gh`, ...) a tag name is later passed to bare.
    pub fn parse(s: &str) -> Result<Self, TagNameError> {
        if is_valid_git_ref_name(s) {
            Ok(Self(s.to_string()))
        } else {
            Err(TagNameError::InvalidGitRefName { name: s.to_string() })
        }
    }

    /// Constructs a tag name without validating it against
    /// Git ref-name rules. Restricted to call sites that can prove
    /// their input is already safe -- see the call site's own comment for
    /// its specific justification. Prefer [`TagName::parse`] everywhere else.
    pub fn new_unchecked(name: String) -> Self {
        Self(name)
    }
}

